	(4369, 'Truy Hồn Phù', 'Thiên Nhãn Phù', 'Tiêu Diêu Phù', 'Hồi Phù', 'B', 'Sử dụng vật phẩm nào thì không cần hỏi cũng có thể biết bạn bè đang ở đâu?'),
	(4608, 'Pasêc', 'Km', 'Năm ánh sáng', 'Ðơn vị thiên văn.', 'A', 'Trong các đơn vị đo chiều dài sau, đơn vị nào là lớn nhất?'),
	(4626, 'Hò', 'Chèo', 'Opera', 'Pop', 'A', 'Thể loại nhạc nào quen thuộc đối với người nông dân Nam Bộ từ xưa?'),
	(4864, 'Giấy gió', 'Giấy vải', 'Giấy hoàng kim', 'Giấy lụa', 'A', 'Tranh Đông Hồ được vẽ trên chất liệu gì?'),
	(4883, 'Động vật', 'Con người', 'Chòm sao', 'Mặt trời', 'A', 'Người ta dùng từ “Zodiac” để chỉ các chòm hoàng đạo, vậy “Zodiac” có nghĩa là gì ?'),
	(257, 'Châu Phi', 'Châu Đại Dương', 'Châu Nam Cực', 'Bắc Mỹ', 'C', 'Châu lục có diện tích nhỏ nhất?'),
	(4940, 'Nhà phát hành không hỗ trợ bất kỳ hình thức mua bán tài khoản nào, hãy nâng cao ý thức bảo mật và bảo vệ tài khoản của mình.', 'Gửi thông tin tài khoản cho đối phương hoặc đăng nhập vào “nền tảng” do đối phương cung cấp để thực hiện “giao dịch”.', 'Cung cấp tài khoản cho người khác để họ xem thông tin nhân vật.', 'Thực hiện việc chuyển vàng và vật phẩm trong game theo hướng dẫn của đối phương.', 'A', 'Khi có người đề nghị mua tài khoản game của bạn với giá cao, bạn nên ( )'),
	(4939, 'Chuyển tiếp đường link chỉnh sửa cho người khác và nhờ họ thay bạn thực hiện.', 'Chuyển tiếp các tài liệu liên quan cho người khác và để họ điền thay.', 'Thực hiện mọi thao tác thông qua kênh chính thức và do chính chủ tự làm từ đầu đến cuối.', 'Tùy tiện điền các thông tin sai lệch.', 'C', 'Khi tài khoản được chỉnh sửa thông tin thông qua quy trình khiếu nại, bạn nên ( )'),
	(4938, 'Thao tác theo các bước mà đối phương hướng dẫn.', 'Chỉ tin vào các sự kiện do chính thức công bố, không để ý đến lời dụ dỗ của người khác.', 'Đưa tài khoản cho người khác để họ trực tiếp thao tác.', 'Giúp đối phương quảng bá, chia sẻ thông tin.', 'B', 'Khi có người bảo bạn thực hiện một thao tác nào đó để nhận quyền lợi đặc biệt hoặc trang bị “thần”, bạn nên ( )'),
	(4937, 'Tùy tiện mở các đường link lạ mà người khác gửi đến.', 'Cung cấp số giấy tờ tùy thân, số điện thoại, tên thật… cho người lạ trên mạng.', 'Tải và sử dụng các “công cụ hỗ trợ” không rõ nguồn gốc.', 'Tất cả các lựa chọn trên đều đúng.', 'D', 'Những hành vi sau đây ( ) có thể dẫn đến thiệt hại tài sản ảo'),
	(4936, 'Người hay chơi cùng có thể cho họ đăng nhập tài khoản.', 'Nếu người khác giúp làm nhiệm vụ hằng ngày thì cho họ đăng nhập tài khoản.', 'Không nên giao tài khoản game của mình cho bất kỳ ai sử dụng.', 'Nếu đối phương nói có thể giúp mình hack tiền hoặc vật phẩm thì có thể đưa tài khoản cho họ đăng nhập.', 'C', 'Khi người khác muốn đăng nhập tài khoản game của bạn, bạn nên ( )'),
	(4935, 'Sử dụng mật khẩu phức tạp và có độ bảo mật cao.', 'Đặt mật khẩu đơn giản như 123456 hoặc các ký tự dễ nhớ.', 'Tất cả tài khoản dùng chung một mật khẩu để dễ sử dụng.', 'Sử dụng ngày sinh của bản thân hoặc của cha mẹ làm mật khẩu.', 'A', 'Khi đặt mật khẩu, bạn nên ( )'),
	(4934, 'Dùng tên thật hoặc thông tin cá nhân để đặt tên tài khoản.', 'Mỗi tài khoản nên dùng tên đăng nhập độc lập, không chứa thông tin cá nhân dễ đoán.', 'Nhiều tài khoản sử dụng cùng một tiền tố hoặc hậu tố, chỉ thay đổi một vài con số.', 'Đặt tên tài khoản và mật khẩu giống nhau hoặc gần giống nhau.', 'B', 'Khi tạo tài khoản, bạn nên ( )');
